INSERT INTO material_items (id, module_id, kind, title, instructions, max_score, due_at_utc, position, time_limit_minutes, shuffle_questions, shuffle_options, anti_cheat, max_violations, show_result, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @mi0 + 1 AS id, @mm0 + 2 AS module_id, 'Activity' AS kind, 'Activity 1: Warm-up practice' AS title, 'Do the exercises in the lesson and write your answers.' AS instructions, 50 AS max_score, (@day0 + INTERVAL -14 DAY + INTERVAL 9 HOUR + INTERVAL 0 MINUTE) AS due_at_utc, 1 AS position, NULL AS time_limit_minutes, 0 AS shuffle_questions, 0 AS shuffle_options, 0 AS anti_cheat, 3 AS max_violations, 0 AS show_result, (@day0 + INTERVAL -36 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -36 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
  UNION ALL SELECT @mi0 + 2, @mm0 + 3, 'Quiz', 'Quiz 1: Check your understanding', 'Answer every question. The timer starts when you open the quiz.', 10, (@day0 + INTERVAL -7 DAY + INTERVAL 9 HOUR + INTERVAL 0 MINUTE), 1, 15, 1, 1, 1, 3, 1, (@day0 + INTERVAL -36 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -36 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @mi0 + 3, @mm0 + 3, 'Activity', 'Activity 2: Worksheet', 'Do the exercises in the lesson and write your answers.', 50, (@day0 + INTERVAL 3 DAY + INTERVAL 9 HOUR + INTERVAL 0 MINUTE), 2, NULL, 0, 0, 0, 3, 0, (@day0 + INTERVAL -36 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -36 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
