UPDATE module_items i JOIN modules m ON m.id = i.module_id AND m.is_exam_set = 1 JOIN teaching_assignments a ON a.id = m.assignment_id JOIN material_modules mm ON mm.subject_id = a.subject_id AND mm.is_exam_set = 1 JOIN material_items x ON x.module_id = mm.id AND x.title = i.title SET i.material_item_id = x.id WHERE i.id > 0 AND i.kind = 'Exam' AND @go = 1;
-- what the provider sent to each course (the teacher's copy), when, and when the teacher first opened it (empty: not opened yet)
INSERT INTO material_deliveries (material_module_id, assignment_id, module_id, sent_by_user_id, created_at_utc, updated_at_utc, opened_at_utc)
SELECT * FROM (
  SELECT @mm0 + 1 AS material_module_id, @ta0 + 1 AS assignment_id, @mo0 + 1 AS module_id, @u_prov AS sent_by_user_id, (@day0 + INTERVAL -2 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -2 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc, NULL AS opened_at_utc
  UNION ALL SELECT @mm0 + 2, @ta0 + 1, @mo0 + 2, @u_prov, (@day0 + INTERVAL -25 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -25 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -23 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @mm0 + 3, @ta0 + 1, @mo0 + 3, @u_prov, (@day0 + INTERVAL -18 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -18 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -16 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @mm0 + 4, @ta0 + 1, @mo0 + 4, @u_prov, (@day0 + INTERVAL -11 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -11 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -9 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE)
