-- ================================================================ 4) Modules opened, work handed in (some graded, some waiting for the teacher)
INSERT INTO module_views (module_id, student_id, first_opened_at_utc)
SELECT * FROM (
  SELECT @mo0 + 2 AS module_id, @s_1 AS student_id, (@day0 + INTERVAL -18 DAY + INTERVAL 4 HOUR + INTERVAL 27 MINUTE) AS first_opened_at_utc
  UNION ALL SELECT @mo0 + 2, @s_2, (@day0 + INTERVAL -22 DAY + INTERVAL 12 HOUR + INTERVAL 20 MINUTE)
  UNION ALL SELECT @mo0 + 2, @s_3, (@day0 + INTERVAL -20 DAY + INTERVAL 13 HOUR + INTERVAL 1 MINUTE)
