SELECT @sg0 + 17, m.user_id, (@day0 + INTERVAL -40 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), NULL FROM (SELECT DISTINCT s.user_id FROM enrollments e JOIN students s ON s.id = e.student_id WHERE e.id > @e0 AND e.id <= @e0 + 40 AND e.strand_id = @strand_HT1) m WHERE @go = 1;

INSERT INTO group_posts (id, group_id, author_user_id, body, parent_post_id, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @gp0 + 1 AS id, @sg0 + 1 AS group_id, @su_1 AS author_user_id, 'Where do we meet on Friday?' AS body, NULL AS parent_post_id, (@day0 + INTERVAL -4 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -4 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
  UNION ALL SELECT @gp0 + 2, @sg0 + 1, @su_2, 'In the library at 4:00 PM. I will bring my notes on the journal.', @gp0 + 1, (@day0 + INTERVAL -4 DAY + INTERVAL 4 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -4 DAY + INTERVAL 4 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @gp0 + 3, @sg0 + 1, @su_3, 'I can come too. Can someone explain the trial balance?', NULL, (@day0 + INTERVAL -3 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -3 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @gp0 + 4, @sg0 + 1, @tu_0, 'Read Module 3 first, then try the task performance. I will answer questions in class.', @gp0 + 3, (@day0 + INTERVAL -3 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -3 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @gp0 + 5, @sg0 + 2, @su_4, 'Here are 5 practice problems for the quiz. Try them before Friday.', NULL, (@day0 + INTERVAL -2 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -2 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @gp0 + 6, @sg0 + 3, @tu_0, 'Reminder: the grades of the first term are due next week.', NULL, (@day0 + INTERVAL -1 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @gp0 + 7, @sg0 + 3, @tu_1, 'Thanks. I will send the review materials here.', @gp0 + 6, (@day0 + INTERVAL -1 DAY + INTERVAL 4 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 4 HOUR + INTERVAL 0 MINUTE)
) AS r WHERE @go = 1;

