  UNION ALL SELECT @sf0 + 5, @su_2, 'Notes on journals.txt', 'text/plain', 112, (@day0 + INTERVAL -1 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE)
